SELECT * FROM GL_ACCOUNT_WITH_WORK_EFFORT_PURPOSE_TYPE_VIEW WHERE ORGANIZATION_PARTY_ID = #{organizationId}
AND LOWER(concat( ACCOUNT_CODE, concat(' - ', ACCOUNT_NAME_LANG))) LIKE LOWER(CONCAT('%', CONCAT(#{val}, '%')))
AND LOWER(concat( ACCOUNT_CODE, concat(' - ', ACCOUNT_NAME))) LIKE LOWER(CONCAT('%', CONCAT(#{val}, '%')))
